from lib import *
S = SS('p34')
steps = [
    step("默认行为:爬虫(8 个 worker、200 个 URL)有 8 个请求在途,收到 SIGINT(Ctrl-C)。asyncio.run 把主任务取消,19 ms 就退出(脚本里捕获了 KeyboardInterrupt,所以退出码 0)。最后的输出是完成 0 个、开始过 8 个、队列里还剩 192 个,8 个在途的请求全部被取消(日志 取消:0、取消:1、取消:2 …,共 8 个);服务器已经收到了这 8 个请求。已经发出的请求白发了,没有处理完的结果也没有保存。", t=tl(S(1)), done=lidx(S(1), '进程最后的输出:{\'done\''), mark=lidx(S(1), '退出码 0', '服务器共收到 8 个请求'), b=bars([['完成', 0, '0'], ['被取消的在途请求', 8, '8'], ['队列里没开始的', 192, '192']], 192, mark=[1], done=[0]), kv=KV([['SIGINT 默认行为', '取消主任务,19 ms 退出'], ['在途的 8 个请求', '全部被取消'], ['结果', '完成 0 个,没有保存']], ['在途的 8 个请求'])),
    step("自己用 loop.add_signal_handler 捕获 SIGINT、设一个标志,让每个 worker 做完手头的请求再退出:8 个请求在途时发信号,313 ms 后退出(服务器每个请求 0.3 秒),完成 8 个、开始过 8 个、被取消 0 个;队列里还剩 192 个没开始的 URL,可以保存下来下次接着抓。完成数等于开始数,没有请求被半路丢掉。", t=tl(S(2)), done=lidx(S(2), '退出码 0,发信号后', '完成数 = 开始数'), b=bars([['完成', 8, '8'], ['被取消', 0, '0'], ['剩下可保存', 192, '192']], 192, done=[0, 1, 2]), kv=KV([['优雅停止', '313 ms 后退出'], ['在途请求', '全部做完,0 个被取消'], ['队列剩余', '192 个可保存']], ['优雅停止'])),
    step("不同信号:没有处理器时,SIGTERM 让进程以 -15 退出(2 ms),SIGKILL 以 -9 退出(5 ms),两种情况下进程都没有机会输出收尾信息。只给 SIGINT 装了处理器时来 SIGTERM:同样以 -15 退出,没有收尾输出。也就是说容器或进程管理器发的 SIGTERM 不会触发你为 SIGINT 写的优雅停止——两种信号都要处理,SIGKILL 则任何处理器都没用。", t=tl(S(3)), done=lidx(S(3), '收到 SIGTERM', '收到 SIGKILL'), mark=lidx(S(3), '只给 SIGINT 装了处理器时收到 SIGTERM'), kv=KV([['SIGTERM(无处理器)', '退出码 -15,无收尾'], ['SIGKILL', '退出码 -9,无法处理'], ['只处理 SIGINT', 'SIGTERM 照样直接杀死']], ['只处理 SIGINT'])),
    step("优雅停止的代价:从发信号到退出,取决于在途请求还要多久。第一批 8 个请求刚到达服务器时发 SIGINT:服务器每个请求 0.3 秒,322 ms 退出;1.0 秒,1023 ms;2.0 秒,2025 ms。每次都是完成 8 个、队列剩 192 个。所以优雅停止需要配一个上限:超过时间就强制取消。", t=tl(S(4)), done=lidx(S(4), '服务器每个请求 0.3 秒', '服务器每个请求 1.0 秒', '服务器每个请求 2.0 秒'), b=bars([['0.3 秒请求:退出用时 ms', 322, '322'], ['1.0 秒请求', 1023, '1023'], ['2.0 秒请求', 2025, '2025']], 2100, done=[0, 1, 2]), kv=KV([['0.3 秒的请求', '322 ms 退出'], ['2.0 秒的请求', '2025 ms 退出'], ['原因', '要等在途请求自己结束']], ['原因'])),
]
A = mkartp('p34', 34, '爬虫,优雅停止,SIGINT,SIGTERM,asyncio,信号处理,Python,真实验证,动画演示',
    '实测 asyncio 爬虫收到信号的行为:默认 SIGINT 取消 8 个在途请求(完成 0 个,19 ms 退出);用 add_signal_handler 优雅停止则让 8 个在途请求完成(313 ms),队列剩下的 192 个可保存;SIGTERM 在没有处理器时直接杀死进程;退出用时等于在途请求剩余时间。',
    '爬虫要停的时候,在途的请求怎么办?直接按 Ctrl-C,已经发出的请求会被取消,结果丢了;容器发 SIGTERM,默认行为更直接。这篇让真实的爬虫进程收到不同的信号,看每种情况下在途请求、队列里剩余的 URL 和退出时间。',
    [('8 对 0', 'Ctrl-C 默认行为取消的在途请求数,对优雅停止取消的在途请求数'), ('-15', '没有处理器时,SIGTERM 让爬虫进程的退出码——没有机会输出任何收尾信息'), ('2025 ms', '服务器每个请求 2 秒时,优雅停止从发信号到退出的用时')],
    [('默认行为', '<p><code>asyncio.run</code> 收到 SIGINT 会取消主任务,在途的请求一起被取消,进程以 <code>KeyboardInterrupt</code> 收尾。8 个已发出的请求全部白费,已经开始的工作没有保存。</p>'),
     ('优雅停止', '<p>在事件循环里用 <code>loop.add_signal_handler(signal.SIGINT, stop.set)</code> 设一个标志,worker 在取下一个 URL 之前检查它;在途的请求自己做完(8 个全完成、0 个取消),队列里剩下的 192 个 URL 没有被丢弃,可以写进状态文件下次再抓(上一篇的做法)。</p>'),
     ('SIGTERM 与 SIGKILL', '<p>容器、systemd、进程管理器通常先发 SIGTERM 再发 SIGKILL。没有为 SIGTERM 装处理器,进程直接以 -15 退出;SIGKILL 任何代码都拦不住。所以优雅停止的处理器要同时装给 SIGINT 和 SIGTERM。</p>'),
     ('等多久', '<p>优雅停止的时间等于在途请求剩下的时间:0.3 秒的请求 322 ms,2 秒的请求 2025 ms。生产里要配一个超时(比如超过 N 秒就取消剩下的),避免一个卡住的请求让进程永远停不下来。</p>')],
    steps,
    [ENV_P + '。爬虫是独立的 Python 子进程(aiohttp,8 个 worker 共 200 个 URL,asyncio.Queue);父进程在本机服务器收到第一批 8 个请求(都在途)后立刻用 Popen.send_signal 发信号;“优雅停止”用 loop.add_signal_handler 设 asyncio.Event,worker 取任务前检查;服务器每个请求停 0.3 秒(最后一节试了 1.0、2.0 秒)',
     '没有验证:Windows 上的信号语义(没有 add_signal_handler);给 SIGINT 与 SIGTERM 都装处理器的效果;第二次 Ctrl-C 强制退出的做法;worker 卡在 CPU 计算(而不是等网络)时信号的响应;多进程爬虫里信号如何传给子进程;容器里 PID 1 的信号特殊性(Docker 系列有专门文章,这里没有测)'],
    '优雅停止')
